def task_func(path, delimiter="/"):
    if not path or not isinstance(path, str):
            raise ValueError("The 'path' must be a non-empty string.")

        components = path.split(delimiter)
        if not components:
            raise ValueError("The 'path' must contain at least one component.")

        disk_usage = []
        for component in components:
            if not component:
                raise ValueError("The 'path' must not contain empty components.")

            try:
                if os.path.exists(component):
                    disk_usage.append((component, shutil.disk_usage(component)))
                else:
                    raise FileNotFoundError(f"The path '{component}' does not exist.")
            except FileNotFoundError as e:
                raise ValueError(f"The path '{component}' does not exist.") from e

        return disk_usage
